{
	"name": "@ps-inc/opencode-obsidian",
	"version": "1.1.1",
	"description": "OpenCode plugin for Obsidian vault integration — PM system, auto-sync, note tools",
	"keywords": [
		"bun",
		"obsidian",
		"opencode",
		"opencode-plugin",
		"vault"
	],
	"author": {
		"name": "ps-inc",
		"email": "ddoucet@ps-inc.io"
	},
	"repository": {
		"type": "git",
		"url": "git+https://gitlab.com/ProSweeper/obsidian-vault-assistant.git"
	},
	"bin": {
		"opencode-obsidian": "dist/cli.js"
	},
	"files": [
		"dist",
		"src/version.ts"
	],
	"type": "module",
	"main": "./dist/index.js",
	"types": "./dist/index.d.ts",
	"exports": {
		".": {
			"types": "./dist/index.d.ts",
			"import": "./dist/index.js"
		},
		"./server": {
			"types": "./dist/index.d.ts",
			"import": "./dist/index.js"
		}
	},
	"publishConfig": {
		"access": "public"
	},
	"scripts": {
		"prepare": "husky",
		"build": "bun build src/index.ts --outdir dist --format esm --target bun && bun build src/cli.ts --outdir dist --format esm --target bun && tsc -p tsconfig.build.json --emitDeclarationOnly",
		"test": "bun test",
		"test:e2e": "bun test src/__test__/e2e",
		"test:coverage": "bun test --coverage",
		"test:coverage:lcov": "bun test --coverage --coverage-reporter=lcov --coverage-dir=coverage",
		"test:ci": "bun test && tsc --noEmit",
		"lint": "oxlint .",
		"lint:fix": "oxlint --fix .",
		"format": "oxfmt .",
		"format:check": "oxfmt --check .",
		"typecheck": "tsc --noEmit",
		"check": "bun run format && bun run lint:fix && bun run typecheck && bun run build && bun run test"
	},
	"devDependencies": {
		"@opencode-ai/plugin": "^1.4.3",
		"@semantic-release/changelog": "^6.0.3",
		"@semantic-release/commit-analyzer": "^13.0.1",
		"@semantic-release/exec": "^7.1.0",
		"@semantic-release/git": "^10.0.1",
		"@semantic-release/gitlab": "^13.3.2",
		"@semantic-release/npm": "^13.1.5",
		"@semantic-release/release-notes-generator": "^14.1.1",
		"bun-types": "^1.3.14",
		"husky": "^9.1.7",
		"jsonc-parser": "^3.3.1",
		"oxfmt": "^0.50.0",
		"oxlint": "^1.65.0",
		"semantic-release": "^24.2.9",
		"typescript": "^6.0.3"
	},
	"peerDependencies": {
		"@opencode-ai/plugin": ">=1.4.3"
	}
}
